def solve(s):
    # Map single symbols to values
    vals = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    i = 0
    while i < len(s):
        # If this is a subtractive pair
        if i+1 < len(s) and vals[s[i]] < vals[s[i+1]]:
            total += vals[s[i+1]] - vals[s[i]]
            i += 2
        else:
            total += vals[s[i]]
            i += 1
    return total

def solve(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if i<0 or i>=rows or j<0 or j>=cols:
                continue
            if visited[i][j] or grid[i][j]==0:
                continue
            visited[i][j]=True
            # neighbors 4-dir
            stack.append((i-1,j))
            stack.append((i+1,j))
            stack.append((i,j-1))
            stack.append((i,j+1))
    count=0
    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count+=1
    return count

