def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Tokens are strings of integers or '+', '-', '*', '/'.
    Division truncates toward zero.
    """
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero without using floating point
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a < 0) ^ (b < 0) else 1
                res = abs(a) // abs(b)
                stack.append(sign * res)
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

